// Query Pre-processing Module
const input = $input.first().json;
const query = (input.body?.query || input.query || '').trim().toLowerCase();

// Extract section identifiers
const sectionPatterns = {
  'CSE_SD_Sec_A': /\b(sd|software\s*dev(elopment)?)\b/i,
  'CSE_AIML_Sec_A': /\b(ai|aiml|artificial\s*intelligence|machine\s*learning|ml)\b/i,
  'CSE_CyberSec_Sec_A': /\b(cys|cyber|cyber\s*sec(urity)?)\b/i,
  'CSE_IBM_Sec_A': /\b(ibm)\b/i,
  'CSE_Xebia_Sec_A': /\b(xebia)\b/i
};

// Extract day
const dayPatterns = {
  'Monday': /\b(mon(day)?)\b/i,
  'Tuesday': /\b(tue(sday)?)\b/i,
  'Wednesday': /\b(wed(nesday)?)\b/i,
  'Thursday': /\b(thu(rsday)?)\b/i,
  'Friday': /\b(fri(day)?)\b/i,
  'Saturday': /\b(sat(urday)?)\b/i
};

// Extract time
const timeMatch = query.match(/(\d{1,2})\s*(?::|\s)\s*(\d{2})?\s*(am|pm)?/i);

let detectedSection = null;
let detectedDay = null;
let detectedTime = null;

for (const [tab, pattern] of Object.entries(sectionPatterns)) {
  if (pattern.test(query)) {
    detectedSection = tab;
    break;
  }
}

for (const [day, pattern] of Object.entries(dayPatterns)) {
  if (pattern.test(query)) {
    detectedDay = day;
    break;
  }
}

if (timeMatch) {
  let hour = parseInt(timeMatch[1]);
  const period = timeMatch[3]?.toLowerCase();
  if (period === 'pm' && hour !== 12) hour += 12;
  if (period === 'am' && hour === 12) hour = 0;
  detectedTime = `${hour}:00`;
}

return [{
  json: {
    originalQuery: query,
    detectedSection,
    detectedDay,
    detectedTime,
    timestamp: new Date().toISOString()
  }
}];

// Response Formatter Module
const agentResponse = $input.first().json;

let response = agentResponse.output || agentResponse.response || agentResponse.text || 'Unable to process your query.';

// Clean up any raw formatting artifacts
response = response.replace(/```/g, '').trim();

return [{
  json: {
    response: response,
    status: 'success',
    timestamp: new Date().toISOString()
  }
}];
